/* ---------- The family newsletter, from the office ----------
   Once a month the director sends families a newsletter through the Kaymbu template. TREE reads the month's
   observations and suggests topics, with the educators' own words and the DRDP connection behind each one, which only
   the director sees. Families see plain words about how children grow, a bonus for school, tips, reading, school and
   farm news, and what is coming up. Every issue is kept, so topics do not repeat in a school year, and every article
   added is kept in a library that comes back when its topic does. Only the director sees and changes this page. */
const nlName=k=>{const [y,m]=k.split("-").map(Number);return new Date(y,m-1,1).toLocaleDateString("en-US",{month:"long",year:"numeric"})};
const nlMonthOnly=k=>{const [y,m]=k.split("-").map(Number);return new Date(y,m-1,1).toLocaleDateString("en-US",{month:"long"})};
const nlShift=(k,n)=>{const [y,m]=k.split("-").map(Number);return nlKey(new Date(y,m-1+n,1))};
const nlSchoolYear=k=>{const [y,m]=k.split("-").map(Number);return m>=8?y:y-1};
const nlLib=()=>newsletters.get("library")||{id:"library",items:[]};
const nlClean=s=>String(s??"").replace(/\*+/g,"").replace(/\s*[—–]\s*/g,", ").trim();
function nlNew(k){return {id:"nl-"+k,month:k,status:"draft",note:"",suggestions:[],topics:[],reading:[],school:[],schoolPhotos:[],coming:[],comingAdded:[],createdAt:Date.now(),by:me()}}

// the month's observations, with the same words kept once and every photo that came with them
function nlObs(k){
  const [y,m]=k.split("-").map(Number);const from=new Date(y,m-1,1).getTime(),to=new Date(y,m,1).getTime();
  const seen=new Map();
  for(const n of [...notices.values()].sort((a,b)=>(a.at||0)-(b.at||0))){
    if(!(n.at>=from&&n.at<to))continue;
    const text=String(n.noticed||"").trim();if(!text&&!n.wonder)continue;
    const key=(n.classroom||"")+"|"+text.slice(0,200);
    let o=seen.get(key);
    if(!o){o={ids:[],photos:[],room:n.classroom||"",date:iso(new Date(n.at)),noticed:text,wonder:String(n.wonder||"").trim(),kids:0};seen.set(key,o)}
    o.ids.push(n.id);if(n.photo&&n.photo.id)o.photos.push(n.id);o.kids=Math.max(o.kids,(n.children||[]).length);
  }
  // a very full month is read from its most recent 220 observations, each kept to a few sentences
  return [...seen.values()].slice(-220).map((o,i)=>Object.assign(o,{ref:"o"+(i+1),noticed:o.noticed.length>700?o.noticed.slice(0,700)+"…":o.noticed}));
}
// how old the children in each class mostly are, so topics can say which ages they show up with
function nlRoomAges(){
  const out={};const now=Date.now();
  for(const c of children.values()){if(c.status&&c.status!=="active")continue;if(!c.dob||!c.classroom)continue;(out[c.classroom]=out[c.classroom]||[]).push((now-parseIso(c.dob).getTime())/(365.25*864e5))}
  return Object.fromEntries(Object.entries(out).map(([r,a])=>{a.sort((x,y)=>x-y);const md=a[Math.floor(a.length/2)];return [r,md<2.5?"mostly two-year-olds":md<3.5?"mostly three-year-olds":"mostly four- and five-year-olds"]}));
}
// a child's first name in words families will read is shown to the director before anything goes out
const nlTopicText=t=>[t.title,t.happening,t.why,(t.grows||[]).map(g=>g.text).join(" "),t.bonus,(t.tips||[]).map(x=>x.lead+" "+x.text).join(" "),(t.photos||[]).map(p=>p.cap).join(" ")].join(" ");
function nlCodesList(){
  const one=v=>Object.entries(DRDP_M[v]||{}).map(([c,m])=>c+" "+m.n).join("; ");
  return "Preschool view. "+one("ptk")+"\nInfant and toddler view. "+one("it");
}
function nlDrdpWords(codes){
  if(!DRDP_TXT)return"";
  return (codes||[]).map(c=>{const parts=[];for(const v of ["it","ptk"]){const m=DRDP_TXT[v]&&DRDP_TXT[v][c];if(!m)continue;
    parts.push(`${v==="it"?"Infant and toddler view":"Preschool view"}, ${c} ${(DRDP_M[v][c]||{}).n||""}. Definition. ${m.def} Levels in order. ${Object.entries(m.levels||{}).map(([k,t])=>(DRDP_LV[k]||k)+", "+t).join(". ")}.`)}
    return parts.join("\n")}).filter(Boolean).join("\n");
}
const nlRules=(behavior)=>`Write for families of young children at Fulton Community School & Farm, a Reggio-inspired, nature-based early childhood program. Use warm, plain words a parent reads in a minute. Never use the words DRDP, measure, domain, level, toddler, or any code or abbreviation. Call the youngest children twos or two-year-olds. ${behavior?"This topic is about a behavior or a challenge, so never name a child or describe a child so a family could tell who it is.":"Use children's first names as the educators wrote them when telling what children did. Never use a last name."} Never use colons, semicolons, em dashes or en dashes. Never use analogies or "not this but that" framing. Say "educator", never "teacher". Say "research shows" only for findings that are well established in early childhood research. ${FULTON_TALK}`;

