function nlAddReading(x,item,topicTitle){
  if(!item.url||!/^https?:\/\//.test(item.url)){toast("Add the article's web address, starting with https.");return false}
  x.reading=(x.reading||[]).filter(r=>r.url!==item.url).concat([{title:item.title||item.url,url:item.url,source:item.source||"",topic:topicTitle||""}]);
  // every article added is kept in the library, tagged with its topic, to come back when the topic does
  const lib=nlLib();const tag=String(topicTitle||"").toLowerCase();
  const have=(lib.items||[]).find(i=>i.url===item.url);
  if(have){if(tag&&!(have.tags||[]).includes(tag))have.tags=(have.tags||[]).concat([tag])}
  else lib.items=(lib.items||[]).concat([{id:"r"+Date.now().toString(36),title:item.title||item.url,url:item.url,source:item.source||"",tags:tag?[tag]:[],addedAt:Date.now(),by:me()}]);
  nlSave(lib,true);nlSave(x,true);return true;
}
// the library's articles that share a word with a topic's title
function nlLibFor(t){const words=String(t.title||"").toLowerCase().split(/[^a-z]+/).filter(w=>w.length>3&&!["when","with","what","they","their","from","into","your","real"].includes(w));
  return (nlLib().items||[]).filter(i=>(i.tags||[]).some(tag=>words.some(w=>tag.includes(w)))||words.some(w=>(i.title||"").toLowerCase().includes(w)))}

