function renderNewsletter(){
  const main=$("#main");
  if(!isDirector()){main.innerHTML=`<div class="head"><span class="eyebrow">Documentation</span><h2 style="margin-top:4px">Family newsletter</h2><div class="sub">The family newsletter is made in the director's view.</div></div>`;return}
  const k=nlCur();const x=nlDoc(k);
  if(!nlEvents[nlShift(k,1)])nlLoadComing(k);
  const months=[...new Set([nlKey(new Date()),nlShift(nlKey(new Date()),-1),nlShift(nlKey(new Date()),1),...[...newsletters.values()].map(d=>d.month).filter(Boolean)])].sort().reverse();
  let h=`<div class="head"><span class="eyebrow">Documentation</span><div class="head-row"><h2 style="margin-top:4px">Family newsletter</h2>
    <select id="nlmonth" style="width:auto" aria-label="Month">${months.map(m=>`<option value="${m}" ${m===k?"selected":""}>${nlName(m)}${nlDoc(m)?.status==="sent"?", sent":nlDoc(m)?", draft":""}</option>`).join("")}</select></div>
    <div class="sub">Once a month, from the office. TREE suggests topics from what educators observed, and you write the newsletter. Only you see this page.</div></div>`;
  if(!x){
    const n=nlObs(k).length;
    h+=`<div class="card nlcard"><b style="font-family:var(--display);font-size:18px">${nlName(k)}</b><p class="muted" style="margin:6px 0 12px">${n?`${n} observation${n===1?"":"s"} kept so far this month. TREE reads them and suggests topics.`:"No observations kept this month yet."}</p>
      <button class="btn" data-nlstart="${k}" ${n?"":"disabled"}>Start the ${nlMonthOnly(k)} newsletter</button></div>`;
    h+=nlArchiveHtml(k);main.innerHTML=h;return;
  }
  const sent=x.status==="sent";
  if(sent)h+=`<div class="card nlcard nlsent">Sent ${x.sentAt?fmtDate(iso(new Date(x.sentAt))):""}. It stays here to look back on, and its topics are not suggested again this school year. <button class="btn small ghost" data-nlunsend="1">Open it again</button></div>`;

  // 1. the director's note
  h+=`<section class="card nlcard"><div class="nlstep">1</div><h3>A note from you</h3><p class="muted nlhint">Your own words at the top. TREE leaves this space for you.</p>
    <textarea class="nlta" data-nlf="note" rows="4" placeholder="What you want families to know this month">${esc(x.note||"")}</textarea></section>`;

  // 2. topics TREE noticed
  const used=new Set((x.topics||[]).map(t=>t.from));
  h+=`<section class="card nlcard"><div class="nlstep">2</div><div class="head-row"><h3>Topics TREE noticed</h3><button class="btn small ghost" data-nlfind="1" ${nlBusy.topics?"disabled":""}>${nlBusy.topics?"Reading the month's observations":(x.suggestions||[]).length?"Look again":"Find topics"}</button></div>
    <p class="muted nlhint">Only you see this part. Each topic shows what educators observed and how it connects to the DRDP. Choose one or two.</p>
    ${(x.suggestions||[]).length?`<div class="nlsugs">${x.suggestions.map(s=>`<div class="nlsug${used.has(s.id)?" used":""}">
      <b class="nlsugt">${esc(s.title)}</b><p>${esc(s.happening)}</p>
      ${s.quotes.length?s.quotes.map(q=>`<blockquote>${esc(q)}</blockquote>`).join(""):""}
      ${s.drdp.length?`<p class="nlsmall"><b>DRDP.</b> ${s.drdp.map(c=>esc(c+" "+((DRDP_M.ptk[c]||DRDP_M.it[c]||{}).n||""))).join(", ")}</p>`:""}
      ${s.ages?`<p class="nlsmall"><b>Ages.</b> ${esc(s.ages)}</p>`:""}
      <p class="nlsmall">${s.notices.length} observation${s.notices.length===1?"":"s"}${s.behavior?". No child photo is offered for a topic about behavior.":s.photos.length?`, ${s.photos.length} photo${s.photos.length===1?"":"s"} to choose from`:""}</p>
      ${used.has(s.id)?`<span class="chip">In this newsletter</span>`:`<button class="btn small" data-nluse="${esc(s.id)}">Use this topic</button>`}</div>`).join("")}</div>`:`<p class="muted">Press Find topics and TREE reads ${nlMonthOnly(k)}'s observations.</p>`}</section>`;

  // 3. each topic, written for families
  (x.topics||[]).forEach((t,i)=>{
    const warn=t.behavior?nlNameWarn(nlTopicText(t)):[];
    const lib=nlLibFor(t).filter(r=>!(x.reading||[]).some(y=>y.url===r.url));
    h+=`<section class="card nlcard" id="nlt-${t.id}"><div class="nlstep">${3+i}</div><div class="head-row"><h3>Topic for families</h3><button class="btn small ghost" data-nlrmtopic="${esc(t.id)}">Remove topic</button></div>
      ${warn.length?`<div class="nlwarn">This topic is about a behavior, and it mentions ${esc(warn.join(", "))}. Leave names out of it so no family can tell who it is about.</div>`:""}
      <label class="nll">Title<input data-nlf="topics.${i}.title" value="${esc(t.title)}"></label>
      <label class="nll">What happened this month<textarea class="nlta" aria-label="What is happening" rows="3" data-nlf="topics.${i}.happening">${esc(t.happening)}</textarea></label>
      <div class="nlphotos">${(t.offer||[]).map(id=>nlThumb(id,(t.photos||[]).some(p=>p.notice===id),`data-nltph="${t.id}" data-id="${id}"`)).join("")}</div>
      ${(t.photos||[]).map((p,j)=>`<label class="nll">Caption for photo ${j+1}<input data-nlf="topics.${i}.photos.${j}.cap" value="${esc(p.cap)}"></label>`).join("")}
      ${t.behavior?`<p class="muted nlhint">No child photo for a topic about behavior, so no family wonders whether it is about their child.</p>`:nlStoryOffer(x,t)}
      <label class="nll">Why it matters<textarea class="nlta" aria-label="Why it matters" rows="3" data-nlf="topics.${i}.why">${esc(t.why)}</textarea></label>
      <div class="nll">How it grows</div>
      ${(t.grows||[]).map((g,j)=>`<div class="nlrow"><input class="nlage" data-nlf="topics.${i}.grows.${j}.age" value="${esc(g.age)}" aria-label="Age"><textarea class="nlta" rows="2" data-nlf="topics.${i}.grows.${j}.text" aria-label="What it looks like">${esc(g.text)}</textarea></div>`).join("")}
      <label class="nll nlbonus">Bonus for school<textarea class="nlta" aria-label="More to know" rows="2" data-nlf="topics.${i}.bonus">${esc(t.bonus)}</textarea></label>
      <div class="head-row" style="margin-top:12px"><div class="nll" style="margin:0">Ideas to try at home</div><span><button class="btn small ghost" data-nltipdraft="${esc(t.id)}">${(t.tips||[]).length?"Draft new tips":"Draft tips for me"}</button> <button class="btn small ghost" data-nltipadd="${esc(t.id)}">Add a tip</button></span></div>
      ${t.tipsDraft?`<p class="nldraft">Drafted by TREE. Rewrite them in your own voice before this goes out.</p>`:""}
      ${(t.tips||[]).length?(t.tips||[]).map((p,j)=>`<div class="nlrow"><input class="nlage" data-nlf="topics.${i}.tips.${j}.lead" value="${esc(nlTxt(p.lead))}" placeholder="Short opening" aria-label="Short opening"><textarea class="nlta" rows="2" data-nlf="topics.${i}.tips.${j}.text" data-talk="1" aria-label="The tip">${esc(p.text)}</textarea><button class="btn small ghost" data-nltiprm="${esc(t.id)}" data-j="${j}" aria-label="Remove this tip">×</button></div>`).join(""):`<p class="muted nlhint">Write your own with Add a tip, or ask TREE for a draft to rewrite.</p>`}
      <div class="head-row" style="margin-top:12px"><div class="nll" style="margin:0">Reading for families</div><button class="btn small ghost" data-nlread="${esc(t.id)}">${(t.readingOffer||[]).length?"Search again":"Suggest reading"}</button></div>
      ${(t.readingOffer||[]).filter(r=>!(x.reading||[]).some(y=>y.url===r.url)).map(r=>`<div class="nlres"><div><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)}</a><span class="muted">. ${esc(r.source)}</span>${r.why?`<div class="nlsmall">${esc(r.why)}</div>`:""}</div><button class="btn small" data-nladdoffer="${esc(t.id)}" data-url="${esc(r.url)}">Add</button></div>`).join("")}
      ${lib.length?`<div class="nlsmall" style="margin-top:8px"><b>From your library</b></div>${lib.map(r=>`<div class="nlres"><div><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)}</a><span class="muted">. ${esc(r.source)}</span></div><button class="btn small" data-nladdlib="${esc(r.id)}" data-topic="${esc(t.id)}">Add</button></div>`).join("")}`:""}
    </section>`;
  });

  // reading chosen, and the director's own
  const step=3+(x.topics||[]).length;
  h+=`<section class="card nlcard"><div class="nlstep">${step}</div><h3>For families who want to read more</h3>
    ${(x.reading||[]).length?(x.reading||[]).map((r,j)=>`<div class="nlres"><div><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)}</a><span class="muted">. ${esc(r.source)}</span></div><button class="btn small ghost" data-nlrmread="${j}" aria-label="Remove">×</button></div>`).join(""):`<p class="muted nlhint">Add articles from the topics above, or your own below. Open each one before it goes to families.</p>`}
    <details class="nlown"><summary>Add your own article or handout</summary>
      <label class="nll">Title<input id="nlrt"></label><label class="nll">Web address<input id="nlru" placeholder="https://"></label><label class="nll">Where it is from<input id="nlrs" placeholder="Such as Early Plate Project"></label>
      <label class="nll">Topic<select id="nlrtopic"><option value="">No topic</option>${(x.topics||[]).map(t=>`<option>${esc(t.title)}</option>`).join("")}</select></label>
      <button class="btn small" data-nladdown="1">Add it</button><p class="muted nlhint">It is kept in your library too, and comes back when its topic does.</p></details></section>`;

  // school and farm
  h+=`<section class="card nlcard"><div class="nlstep">${step+1}</div><div class="head-row"><h3>Around the school and farm</h3><button class="btn small ghost" data-nlschool="1">${(x.school||[]).length?"Suggest more":"Suggest from observations"}</button></div>
    <p class="muted nlhint">Only what spans the school, such as the animals, the garden, staff news, events and policy updates.</p>
    ${(x.school||[]).map((s,j)=>`<div class="nlrow"><textarea class="nlta" rows="2" aria-label="School news" data-nlf="school.${j}.text">${esc(s.text)}</textarea><button class="btn small ghost" data-nlrmschool="${j}" aria-label="Remove">×</button></div>`).join("")}
    <button class="btn small ghost" data-nladdschool="1">Add a line</button>
    ${(x.schoolOffer||[]).length?`<div class="nlphotos">${x.schoolOffer.map(id=>nlThumb(id,(x.schoolPhotos||[]).some(p=>p.notice===id),`data-nlsph="${id}"`)).join("")}</div>`:""}
    ${(x.schoolPhotos||[]).map((p,j)=>`<label class="nll">Caption for photo ${j+1}<input data-nlf="schoolPhotos.${j}.cap" value="${esc(p.cap)}"></label>`).join("")}</section>`;

  // coming up
  const ev=nlEvents[nlShift(k,1)];const chosen=new Set((x.coming||[]).map(c=>c.date+"|"+c.text));
  // where the month's food came from, the same content as the farm sheet for families
  {const ft=farmNewsletterText(x.month);h+=`<section class="card nlcard"><h3>From our farms</h3>
    ${ft?`<label class="nlcheck"><input type="checkbox" data-nlfarms="1" ${x.farms?"checked":""}> Include where this month's lunches and snacks came from</label>${x.farms?`<div class="muted" style="white-space:pre-line;margin-top:6px">${esc(ft)}</div>`:""}`:`<p class="muted nlhint">No orders are kept for this month yet, so there is nothing to show.</p>`}</section>`}
  // thank you to the families who gave time this month, every family named
  {const tt=famThanksText(x.month);h+=`<section class="card nlcard"><h3>Thank you, families</h3>
    ${tt?`<label class="nlcheck"><input type="checkbox" data-nlthanks="1" ${x.thanks!==false?"checked":""}> Thank the families who gave time this month</label>${x.thanks!==false?`<div class="muted" style="white-space:pre-line;margin-top:6px">${esc(tt)}</div>`:""}`:`<p class="muted nlhint">No family has logged time this month yet.</p>`}</section>`}
  h+=`<section class="card nlcard"><div class="nlstep">${step+2}</div><h3>Coming up in ${nlMonthOnly(nlShift(k,1))}</h3>
    ${!ev?`<p class="muted">Reading the school calendar</p>`:ev.failed?`<p class="muted">The school calendar could not be read just now. Add dates yourself below.</p>`:ev.items.length?ev.items.map(e=>`<label class="nlcheck"><input type="checkbox" data-nlcome="${esc(e.date+"|"+e.text)}" ${chosen.has(e.date+"|"+e.text)?"checked":""}> <b>${esc(nlDay(e.date))}.</b> ${esc(e.text)}</label>`).join(""):`<p class="muted">Nothing on the school calendar for ${nlMonthOnly(nlShift(k,1))} yet.</p>`}
    ${(x.coming||[]).filter(c=>c.own).map(c=>`<div class="nlres"><div><b>${esc(c.date?nlDay(c.date):"")}.</b> ${esc(c.text)}</div><button class="btn small ghost" data-nlrmcome="${esc(c.date+"|"+c.text)}" aria-label="Remove">×</button></div>`).join("")}
    <div class="nlrow"><input type="date" id="nlcd" aria-label="Date"><input id="nlct" placeholder="What is happening"><button class="btn small ghost" data-nladdcome="1">Add</button></div></section>`;

  // finish
  h+=`<section class="card nlcard"><div class="nlstep">${step+3}</div><h3>Send it</h3>
    <p class="muted nlhint">Copy each block into your Kaymbu template and add the photos. Word and PDF copies are for your records and the front entrance.</p>
    <div class="actions"><button class="btn" data-nlkaymbu="1">${nlKaymbu?"Hide the Kaymbu blocks":"Copy for Kaymbu"}</button><button class="btn ghost" data-nlword="1">Download Word</button><button class="btn ghost" data-nlpdf="1">Download PDF</button>${x.posted?"":`<button class="btn ghost" data-nlpost="1">Post to the Family page</button>`}${sent?"":`<button class="btn ghost" data-nlsent="1">Mark as sent</button>`}<button class="btn ghost danger" data-nldel="1">Delete this newsletter</button></div>
    ${x.posted?`<div class="nlres" style="margin-top:10px"><div>On the Family page since ${esc(fmtDate(iso(new Date(x.posted.at))))}.${x.updatedAt>(x.posted.at||0)+5000?" You have changed it since, so update it for families to see the changes.":""}</div><span class="actions"><button class="btn small" data-nlpost="1">Update it</button><button class="btn small ghost" data-nlunpost="1">Take it down</button></span></div>`:""}
    ${nlKaymbu?nlKaymbuHtml(x):""}</section>`;
  h+=nlArchiveHtml(k);
  main.innerHTML=h;
  main.querySelectorAll("textarea.nlta").forEach(ta=>{try{autoGrow(ta)}catch(e){}});
}
function nlArchiveHtml(k){
  const past=[...newsletters.values()].filter(d=>d.month&&d.month!==k).sort((a,b)=>b.month.localeCompare(a.month));
  const lib=nlLib().items||[];
  return `<section class="card nlcard nlarch"><h3>Past newsletters</h3>${past.length?past.map(d=>`<button class="item" data-nlopen="${d.month}"><span class="nm">${nlName(d.month)}</span><span class="cnt">${(d.topics||[]).map(t=>esc(t.title)).join(", ")||"No topics yet"}${d.status==="sent"?"":", draft"}</span></button>`).join(""):`<p class="muted">Each newsletter is kept here once it is started.</p>`}
    <p class="muted nlhint" style="margin-top:10px">${lib.length} article${lib.length===1?"":"s"} in your library.</p></section>`;
}

// the newsletter as plain blocks, the way they go into the Kaymbu template
function nlBlocks(x){
  const B=[];
  if((x.note||"").trim())B.push({h:"A note from the director",text:x.note.trim()});
  for(const t of x.topics||[]){
    const p=[t.title,"",t.happening,"","Why it matters",t.why,""];
    if((t.grows||[]).length){p.push("How it grows");for(const g of t.grows)p.push(`${g.age}. ${g.text}`);p.push("")}
    if(t.bonus)p.push("Bonus for school. "+t.bonus,"");
    if((t.tips||[]).length){p.push("Ideas to try at home");for(const tp of t.tips)p.push(nlTxt(`${tp.lead} ${tp.text}`).trim())}
    B.push({h:t.title,text:p.join("\n").replace(/\n{3,}/g,"\n\n").trim(),photos:t.photos||[]});
  }
  if((x.reading||[]).length)B.push({h:"For families who want to read more",text:x.reading.map(r=>`${r.title}${r.source?", "+r.source:""}\n${r.url}`).join("\n\n")});
  const sch=(x.school||[]).map(s=>s.text.trim()).filter(Boolean);
  if(sch.length)B.push({h:"Around the school and farm",text:sch.join("\n\n"),photos:x.schoolPhotos||[]});
  {const ft=x.farms?farmNewsletterText(x.month):"";if(ft)B.push({h:"From our farms",text:ft})}
  {const tt=x.thanks!==false?famThanksText(x.month):"";if(tt)B.push({h:"Thank you, families",text:tt})}
  if((x.coming||[]).length)B.push({h:"Coming up",text:[...x.coming].sort((a,b)=>String(a.date).localeCompare(String(b.date))).map(c=>`${c.date?nlDay(c.date)+". ":""}${c.text}`).join("\n")});
  return B;
}
function nlKaymbuHtml(x){
  const B=nlBlocks(x);
  if(!B.length)return `<p class="muted">Nothing written yet.</p>`;
  const warn=nlNameWarn((x.topics||[]).filter(t=>t.behavior).map(nlTopicText).join(" "));
  return `${warn.length?`<div class="nlwarn">A topic about a behavior mentions ${esc(warn.join(", "))}. Leave names out of it before copying.</div>`:""}${(x.topics||[]).some(t=>t.tipsDraft)?`<div class="nlwarn">Some tips are still TREE's draft.</div>`:""}
    ${B.map((b,j)=>`<div class="nlblock"><div class="head-row"><b>${esc(b.h)}</b><button class="btn small" data-nlcopy="${j}">Copy</button></div><textarea class="nlta" rows="5" readonly id="nlb-${j}">${esc(b.text)}</textarea>
    ${(b.photos||[]).length?`<div class="nlphotos">${b.photos.map(p=>{const n=notices.get(p.notice);return n?`<span class="nlphs"><img src="${esc(photoThumb(n))}" alt=""><button class="btn small ghost" data-nlsave="${p.notice}">Save photo</button></span>`:""}).join("")}</div>`:""}</div>`).join("")}`;
}

function nlSetPath(x,path,val){const ks=path.split(".");let o=x;for(let i=0;i<ks.length-1;i++){o=o[/^\d+$/.test(ks[i])?Number(ks[i]):ks[i]];if(o==null)return}o[ks[ks.length-1]]=val}
document.addEventListener("input",e=>{
  if(view!=="newsletter")return;const el=e.target;if(!el.dataset||!el.dataset.nlf)return;
  const x=nlDoc(nlCur());if(!x)return;nlSetPath(x,el.dataset.nlf,el.value);
  const m=el.dataset.nlf.match(/^topics\.(\d+)\.tips\./);if(m&&x.topics[+m[1]])x.topics[+m[1]].tipsDraft=false;
  if(el.tagName==="TEXTAREA")try{autoGrow(el)}catch(err){}
  nlSave(x);
});
document.addEventListener("change",e=>{
  if(view!=="newsletter")return;const el=e.target;
  if(el.id==="nlmonth"){nlMonth=el.value;LS.set("tree.nlmonth",nlMonth);nlKaymbu=false;renderNewsletter();return}
  if(el.dataset&&el.dataset.nlcome){const x=nlDoc(nlCur());if(!x)return;const [date,...rest]=el.dataset.nlcome.split("|");const text=rest.join("|");
    x.coming=(x.coming||[]).filter(c=>!(c.date===date&&c.text===text));if(el.checked)x.coming.push({date,text});nlSave(x)}
});
document.addEventListener("click",async e=>{
  if(view!=="newsletter")return;const t=e.target.closest("button");if(!t)return;const d=t.dataset;
  const k=nlCur();let x=nlDoc(k);
  if(d.nlstart){if(!sample){toast("TREE's reading help is not available right now.");return}x=nlNew(d.nlstart);nlDeleted.delete(x.id);nlSave(x,true);renderNewsletter();nlFindTopics(x,$("[data-nlfind]"));return}
  if(d.nlopen){nlMonth=d.nlopen;LS.set("tree.nlmonth",nlMonth);nlKaymbu=false;renderNewsletter();jumpTop();return}
  if(!x)return;
  if(d.nlfind){nlFindTopics(x,t);return}
  if(d.nluse){const s=(x.suggestions||[]).find(y=>y.id===d.nluse);if(s)nlUseTopic(x,s,t);return}
  if(d.nlrmtopic){if(!confirm("Remove this topic from the newsletter?"))return;x.topics=x.topics.filter(y=>y.id!==d.nlrmtopic);nlSave(x,true);renderNewsletter();return}
  if(d.nltst){const tp=x.topics.find(y=>y.id===d.nltst);const st=stories.get(d.id);if(!tp||!st||tp.behavior)return;const on=(tp.photos||[]).some(p=>p.story===st.id);
    if(on)tp.photos=tp.photos.filter(p=>p.story!==st.id);else{if((tp.photos||[]).length>=2){toast("Two photos fit a topic best. Take one out first.");return}tp.photos=(tp.photos||[]).concat([{notice:st.coverPhoto||storyPhotoIds(st)[0],cap:nlStoryCap(st),story:st.id}])}
    nlSave(x);renderNewsletter();return}
  if(d.nltph){const tp=x.topics.find(y=>y.id===d.nltph);if(!tp)return;const has=(tp.photos||[]).some(p=>p.notice===d.id);
    if(has)tp.photos=tp.photos.filter(p=>p.notice!==d.id);else{if((tp.photos||[]).length>=2){toast("Two photos fit a topic best. Take one out first.");return}tp.photos=(tp.photos||[]).concat([{notice:d.id,cap:nlCaption(notices.get(d.id))}])}
    nlSave(x);renderNewsletter();return}
  if(d.nlsph){const has=(x.schoolPhotos||[]).some(p=>p.notice===d.nlsph);
    if(has)x.schoolPhotos=x.schoolPhotos.filter(p=>p.notice!==d.nlsph);else{if((x.schoolPhotos||[]).length>=2){toast("Two photos fit this part best. Take one out first.");return}x.schoolPhotos=(x.schoolPhotos||[]).concat([{notice:d.nlsph,cap:nlCaption(notices.get(d.nlsph))}])}
    nlSave(x);renderNewsletter();return}
  if(d.nltipdraft){const tp=x.topics.find(y=>y.id===d.nltipdraft);if(!tp)return;if((tp.tips||[]).length&&!confirm("Replace these tips with a new draft?"))return;nlDraftTips(x,tp,t);return}
  if(d.nltipadd){const tp=x.topics.find(y=>y.id===d.nltipadd);if(!tp)return;tp.tips=(tp.tips||[]).concat([{lead:"",text:""}]);nlSave(x);renderNewsletter();return}
  if(d.nltiprm){const tp=x.topics.find(y=>y.id===d.nltiprm);if(!tp)return;tp.tips.splice(+d.j,1);nlSave(x);renderNewsletter();return}
  if(d.nlread){const tp=x.topics.find(y=>y.id===d.nlread);if(tp)nlSuggestReading(x,tp,t);return}
  if(d.nladdoffer){const tp=x.topics.find(y=>y.id===d.nladdoffer);const r=tp&&(tp.readingOffer||[]).find(y=>y.url===d.url);if(r&&nlAddReading(x,r,tp.title)){toast("Added, and kept in your library.");renderNewsletter()}return}
  if(d.nladdlib){const r=(nlLib().items||[]).find(y=>y.id===d.nladdlib);const tp=x.topics.find(y=>y.id===d.topic);if(r&&nlAddReading(x,r,tp&&tp.title))renderNewsletter();return}
  if(d.nladdown){const item={title:$("#nlrt").value.trim(),url:$("#nlru").value.trim(),source:$("#nlrs").value.trim()};if(!item.title){toast("Add the article's title.");return}if(nlAddReading(x,item,$("#nlrtopic").value)){toast("Added, and kept in your library.");renderNewsletter()}return}
  if(t.hasAttribute("data-nlrmread")){x.reading.splice(+d.nlrmread,1);nlSave(x);renderNewsletter();return}
  if(d.nlschool){nlSuggestSchool(x,t);return}
  if(d.nladdschool){x.school=(x.school||[]).concat([{text:""}]);nlSave(x);renderNewsletter();return}
  if(t.hasAttribute("data-nlrmschool")){x.school.splice(+d.nlrmschool,1);nlSave(x);renderNewsletter();return}
  if(d.nladdcome){const date=$("#nlcd").value,text=$("#nlct").value.trim();if(!text){toast("Write what is happening.");return}x.coming=(x.coming||[]).concat([{date,text,own:true}]);nlSave(x);renderNewsletter();return}
  if(d.nlrmcome){const [date,...rest]=d.nlrmcome.split("|");const text=rest.join("|");x.coming=x.coming.filter(c=>!(c.own&&c.date===date&&c.text===text));nlSave(x);renderNewsletter();return}
  if(d.nlkaymbu){nlKaymbu=!nlKaymbu;renderNewsletter();if(nlKaymbu)setTimeout(()=>{const b=$(".nlblock");if(b)b.scrollIntoView({block:"start",behavior:"smooth"})},60);return}
  if(t.hasAttribute("data-nlcopy")){copyText($("#nlb-"+d.nlcopy));return}
  if(d.nlsave){const n=notices.get(d.nlsave);if(!n||!n.photo)return;try{const r=await fetchPhoto(window.FP_ORIGINAL_URL(n.photo.id));const blob=await r.blob();
      await downloads.save({filename:`Fulton Community School newsletter ${nlMonthOnly(k)} photo ${n.photo.id.slice(0,6)}.jpg`,data:blob})}catch(err){toast("The photo could not be saved. Try again.")}return}
  if(d.nlword){nlWord(x);return}
  if(d.nlpdf){nlPdf(x);return}
  if(d.nlsent){if(nlNameWarn((x.topics||[]).filter(t=>t.behavior).map(nlTopicText).join(" ")).length&&!confirm("A topic about a behavior names a child. Mark it as sent anyway?"))return;x.status="sent";x.sentAt=Date.now();nlSave(x,true);toast("Marked as sent. It stays in Past newsletters.");renderNewsletter();return}
  // the newsletter goes on the Family page only when the director posts it, as it reads at that moment
  if(d.nlpost){if(nlNameWarn((x.topics||[]).filter(t=>t.behavior).map(nlTopicText).join(" ")).length){toast("A topic about a behavior names a child. Take the name out before posting.");return}
    const B=nlBlocks(x);if(!B.length){toast("Nothing is written yet.");return}
    const blocks=tidyWords(B.map(b=>({h:nlTxt(b.h),text:nlTxt(b.text).replace(new RegExp("^"+nlTxt(b.h).replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+"\\s*\\n+"),""),photos:(b.photos||[]).map(p=>{const n=notices.get(p.notice);return n&&n.photo&&n.photo.id?{id:n.photo.id,cap:p.cap||""}:null}).filter(Boolean)})));
    if(!confirm(x.posted?"Update the newsletter on the Family page with what is here now?":`Post the ${nlName(x.month)} newsletter to the Family page? Every family will see it.`))return;
    x.posted={title:`The ${nlName(x.month)} newsletter`,blocks,at:Date.now()};nlSave(x,true);toast("On the Family page.");renderNewsletter();return}
  if(d.nlunpost){if(!confirm("Take the newsletter off the Family page?"))return;x.posted=null;nlSave(x,true);toast("Taken off the Family page.");renderNewsletter();return}
  if(d.nlunsend){x.status="draft";nlSave(x,true);renderNewsletter();return}
  if(d.nldel){if(!confirm(`Delete the ${nlName(x.month)} newsletter? Its topics, tips and photos choices are removed. Articles stay in your library.`))return;
    clearTimeout(nlTimers[x.id]);delete nlTimers[x.id];nlDeleted.add(x.id);newsletters.delete(x.id);nlKaymbu=false;
    if(db)db.doc("newsletters/"+x.id).delete().then(()=>toast("The newsletter is deleted.")).catch(()=>toast("Could not delete the newsletter. Check your connection."));
    renderNewsletter();jumpTop();return}
});

// photos for the printed copies, at a size that prints well
async function nlPhotos(x){
  const list=[...(x.topics||[]).flatMap(t=>t.photos||[]),...(x.schoolPhotos||[])].map(p=>notices.get(p.notice)).filter(n=>n&&n.photo&&n.photo.id);
  await loadPhotos([{photos:list.map(n=>({key:"nl:"+n.id,src:window.FP_ORIGINAL_URL(n.photo.id)}))}]);
}
const nlIm=p=>photoCache.get("nl:"+p.notice);
async function nlWord(x){
  let D;try{D=await TREE_KIT.word()}catch(e){toast("The Word tool did not load. Check your connection and reload.");return}
  toast("Preparing the Word file");await nlPhotos(x);await loadPrintFonts();
  const {Document,Packer,Paragraph,TextRun,ImageRun,Table,TableRow,TableCell,WidthType,ShadingType,BorderStyle,AlignmentType,ExternalHyperlink,Footer,LevelFormat}=D;
  const MOSS="2B5A40",INK="1B2920",MUTED="5B6B61",LINE="C6D0C3",W=9840,F=PF.buf?PF.word.fr:"Arial";
  // em dashes become commas, the way the PDF prints them, and bold words use the school's semibold and headings its display face
  // Andika runs a little wider than most faces, so the words are set at 10 points to keep the newsletter to four pages
  const r=(t,o)=>{o=Object.assign({},o||{});if(PF.buf)o.font=PF.word.fr;if(PF.buf&&o.size)o.size=Math.round(o.size*.91);return new TextRun(Object.assign({text:nlTxt(t).replace(/\s*\u2014\s*/g,", "),font:F,size:PF.buf?20:22,color:INK},o))};
  const P=(kids,o)=>new Paragraph(Object.assign({children:Array.isArray(kids)?kids:[r(kids)],spacing:{after:140,line:300}},o||{}));
  const H=(t,sz,o)=>new Paragraph(Object.assign({children:[r(t,{size:sz,bold:true,color:MOSS})],spacing:{before:280,after:120},keepNext:true},o||{}));
  const sub=t=>new Paragraph({children:[r(t,{size:24,bold:true})],spacing:{before:160,after:80},keepNext:true});
  const rule=()=>new Paragraph({children:[],spacing:{before:200,after:0},border:{top:{style:BorderStyle.SINGLE,size:4,color:LINE,space:8}}});
  const bul=kids=>new Paragraph({children:kids,numbering:{reference:"dots",level:0},spacing:{after:90,line:290}});
  const none={style:BorderStyle.NONE,size:0,color:"FFFFFF"},nb={top:none,bottom:none,left:none,right:none};
  const photoRow=ps=>{ps=ps.filter(p=>nlIm(p));if(!ps.length)return[];const col=Math.floor(W/ps.length);
    const cell=p=>{const im=nlIm(p);const maxW=ps.length>1?290:420,maxH=ps.length>1?370:400;let w=maxW,h=w*im.h/im.w;if(h>maxH){h=maxH;w=h*im.w/im.h}
      return new TableCell({width:{size:col,type:WidthType.DXA},borders:nb,margins:{right:160},children:[new Paragraph({children:[new ImageRun({type:"jpg",data:im.bytes,transformation:{width:Math.round(w),height:Math.round(h)}})],spacing:{after:60}}),new Paragraph({children:[r(p.cap,{size:18,color:MUTED})],spacing:{after:160,line:260}})]})};
    return [new Table({width:{size:col*ps.length,type:WidthType.DXA},columnWidths:ps.map(()=>col),borders:Object.assign({insideHorizontal:none,insideVertical:none},nb),rows:[new TableRow({children:ps.map(cell)})]})]};
  const ch=[];
  ch.push(P([r("FULTON COMMUNITY SCHOOL & FARM",{size:18,bold:true,color:MUTED,characterSpacing:40})],{spacing:{after:60}}));
  ch.push(new Paragraph({children:[r("Family newsletter, "+nlName(x.month),{size:40,bold:true,color:MOSS})],spacing:{after:200}}));
  if((x.note||"").trim()){ch.push(H("A note from the director",28));for(const para of x.note.trim().split(/\n\s*\n/))ch.push(P(para.replace(/\n/g," ")))}
  for(const t of x.topics||[]){
    ch.push(rule());ch.push(H(t.title,30,{before:120}));ch.push(...photoRow(t.photos||[]));
    if(t.happening)ch.push(P(t.happening));
    if(t.why){ch.push(sub("Why it matters"));ch.push(P(t.why))}
    if((t.grows||[]).length){ch.push(sub("How it grows"));for(const g of t.grows)ch.push(bul([r(g.age+". ",{bold:true,color:MOSS}),r(g.text)]))}
    if(t.bonus)ch.push(new Table({width:{size:W,type:WidthType.DXA},columnWidths:[W],rows:[new TableRow({children:[new TableCell({width:{size:W,type:WidthType.DXA},shading:{type:ShadingType.CLEAR,color:"auto",fill:"FBF3E4"},borders:{top:none,bottom:none,right:none,left:{style:BorderStyle.SINGLE,size:24,color:"9A5B07"}},margins:{top:140,bottom:140,left:240,right:240},children:[new Paragraph({children:[r("Bonus for school. ",{bold:true,color:"9A5B07"}),r(t.bonus)],spacing:{after:0,line:290}})]})]})]}));
    if((t.tips||[]).length){ch.push(sub("Ideas to try at home"));for(const p of t.tips)ch.push(bul([r((p.lead||"")+" ",{bold:true}),r(p.text)]))}
  }
  if((x.reading||[]).length){ch.push(rule());ch.push(H("For families who want to read more",28,{before:120}));for(const it of x.reading)ch.push(bul([new ExternalHyperlink({link:it.url,children:[r(it.title,{color:"245B78",underline:{}})]}),r(it.source?(/[.?!]$/.test(it.title)?" ":". ")+it.source:"",{color:MUTED})]))}
  const sch=(x.school||[]).map(s=>s.text.trim()).filter(Boolean);
  if(sch.length){ch.push(rule());ch.push(H("Around the school and farm",28,{before:120}));ch.push(...photoRow(x.schoolPhotos||[]));for(const s of sch)ch.push(bul([r(s)]))}
  {const ft=x.farms?farmNewsletterText(x.month):"";if(ft){ch.push(rule());ch.push(H("From our farms",28,{before:120}));for(const pp of ft.split(/\n\n/))ch.push(P(pp))}}
  if((x.coming||[]).length){ch.push(rule());ch.push(H("Coming up",28,{before:120}));for(const c of [...x.coming].sort((a,b)=>String(a.date).localeCompare(String(b.date))))ch.push(bul([r(c.date?nlDay(c.date)+". ":"",{bold:true}),r(c.text)]))}
  const wf=wordFonts();const doc=TREE_KIT.wordFile(D,{creator:"Fulton Community School",title:"Family newsletter, "+nlName(x.month),...(wf.length?{fonts:wf}:{}),styles:{default:{document:{run:{font:F,size:22}}}},
    numbering:{config:[{reference:"dots",levels:[{level:0,format:LevelFormat.BULLET,text:"•",alignment:AlignmentType.LEFT,style:{paragraph:{indent:{left:360,hanging:240}}}}]}]},
    sections:[{properties:{page:{size:{width:12240,height:15840},margin:{top:1080,bottom:1080,left:1200,right:1200}}},footers:{default:new Footer({children:[new Paragraph({alignment:AlignmentType.CENTER,children:[r("Fulton Community School",{size:16,color:MUTED})]})]})},children:ch}]});
  const blob=await TREE_KIT.wordBlob(D,doc);
  await downloads.save({filename:`Fulton Community School family newsletter ${nlName(x.month)}.docx`,data:blob});
}
// tips drafted with markdown keep their words and lose the asterisks
const nlTxt=t=>String(t??"").replace(/\*+/g,"").replace(/ +([.,])/g,"$1");
async function nlPdf(x){
  if(!window.jspdf){toast("The PDF tool did not load. Check your connection and reload.");return}
  toast("Preparing the PDF");await nlPhotos(x);await loadPrintFonts();
  // set at full size, then a little smaller when that saves a page with only a few lines on it
  const build=sc=>{const doc=TREE_KIT.pdf({unit:"pt",format:"letter"});
  const L=54,R=PW-54,TW=R-L,BOT=PH-60;let y=60;const bs=10.5*sc,blh=bs*1.42;
  const ink=()=>doc.setTextColor(...C.ink),moss=()=>doc.setTextColor(...C.moss),mut=()=>doc.setTextColor(...C.muted);
  const need=hh=>{if(y+hh>BOT){doc.addPage();y=60}};
  const para=(t,o={})=>{const sz=(o.size||10.5)*sc;pfont(doc,o.bold?"fs":"fr",sz);(o.color||ink)();const lines=doc.splitTextToSize(clean(nlTxt(t)),o.w||TW);const lh=sz*1.42;
    lines.forEach((ln,i)=>{need(i===0&&lines.length>1?lh*2:lh);doc.text(ln,o.x||L,y+lh*.75);y+=lh});y+=(o.after??7)*sc};
  // a heading always has at least two lines of its words under it on the same page
  const head=(t,sz)=>{sz*=sc;pfont(doc,"bs",sz);const ls=doc.splitTextToSize(clean(t),TW);need(6+ls.length*sz*1.25+5+blh*2.2);y+=6;moss();for(const ln of ls){doc.text(ln,L,y+sz*.8);y+=sz*1.25}y+=5};
  const sub=t=>{need(18*sc+blh*2.2);pfont(doc,"fs",11.5*sc);ink();doc.text(clean(t),L,y+10*sc);y+=18*sc};
  const bullet=(lead,t)=>{const lh=blh;lead=clean(nlTxt(lead));const words=clean(nlTxt(t)).split(/\s+/).filter(Boolean);
    pfont(doc,"fs",bs);const leadW=lead?doc.getTextWidth(lead+" "):0;pfont(doc,"fr",bs);
    let first="";while(words.length&&doc.getTextWidth((first?first+" ":"")+words[0])<=TW-14-leadW)first=(first?first+" ":"")+words.shift();
    const rest=words.length?doc.splitTextToSize(words.join(" "),TW-14):[];
    need(rest.length?lh*2:lh);doc.setFillColor(...C.moss);doc.circle(L+3,y+lh*.45,1.6,"F");
    if(lead){pfont(doc,"fs",bs);moss();doc.text(lead,L+14,y+lh*.75)}pfont(doc,"fr",bs);ink();doc.text(first,L+14+leadW,y+lh*.75);y+=lh;
    for(const ln of rest){need(lh);doc.text(ln,L+14,y+lh*.75);y+=lh}y+=4*sc};
  const rule=()=>{need(24);y+=8;doc.setDrawColor(...C.line);doc.setLineWidth(.6);doc.line(L,y,R,y);y+=10};
  const photos=ps=>{ps=ps.filter(p=>nlIm(p));if(!ps.length)return;const gap=14,cw=ps.length>1?(TW-gap)/2:TW*.62,mh=(ps.length>1?250:300)*sc;
    const dims=ps.map(p=>{const im=nlIm(p);let w=cw,h=w*im.h/im.w;if(h>mh){h=mh;w=h*im.w/im.h}return {im,w,h,p}});const rowH=Math.max(...dims.map(d=>d.h));
    need(rowH+34);let xx=L;let capH=0;
    for(const dm of dims){doc.addImage(dm.im.url,"JPEG",xx,y,dm.w,dm.h);pfont(doc,"fr",8.6);mut();const cl=doc.splitTextToSize(clean(dm.p.cap),cw);cl.slice(0,3).forEach((ln,i)=>doc.text(ln,xx,y+rowH+11+i*11));capH=Math.max(capH,Math.min(cl.length,3)*11);xx+=cw+gap}
    y+=rowH+capH+16};
  pfont(doc,"fs",8.5);mut();doc.setCharSpace(1);doc.text("FULTON COMMUNITY SCHOOL & FARM",L,y);doc.setCharSpace(0);y+=10;
  head("Family newsletter, "+nlName(x.month),22);
  if((x.note||"").trim()){head("A note from the director",14);for(const pp of x.note.trim().split(/\n\s*\n/))para(pp.replace(/\n/g," "))}
  for(const t of x.topics||[]){rule();head(t.title,17);photos(t.photos||[]);if(t.happening)para(t.happening);
    if(t.why){sub("Why it matters");para(t.why)}
    if((t.grows||[]).length){sub("How it grows");for(const g of t.grows)bullet(g.age+".",g.text)}
    if(t.bonus){pfont(doc,"fr",bs);const lines=doc.splitTextToSize(clean("Bonus for school. "+nlTxt(t.bonus)),TW-30);const hh=lines.length*blh+18;need(hh+6);y+=4;
      doc.setFillColor(251,243,228);doc.rect(L,y,TW,hh,"F");doc.setFillColor(...C.marigold);doc.rect(L,y,3,hh,"F");
      lines.forEach((ln,i)=>{if(i===0){pfont(doc,"fs",bs);doc.setTextColor(154,91,7);doc.text("Bonus for school.",L+16,y+9+bs);const bw=doc.getTextWidth("Bonus for school. ");pfont(doc,"fr",bs);ink();doc.text(ln.replace(/^Bonus for school\.\s*/,""),L+16+bw,y+9+bs)}else{pfont(doc,"fr",bs);ink();doc.text(ln,L+16,y+9+bs+i*blh)}});y+=hh+10}
    if((t.tips||[]).length){sub("Ideas to try at home");for(const p of t.tips)bullet(p.lead,p.text)}}
  if((x.reading||[]).length){rule();head("For families who want to read more",14);for(const it of x.reading){bullet("",it.title+(it.source?(/[.?!]$/.test(it.title)?" ":". ")+it.source:""));pfont(doc,"fr",8.6);mut();doc.textWithLink(clean(it.url).slice(0,95),L+14,y+2,{url:it.url});y+=12}}
  const sch=(x.school||[]).map(s=>s.text.trim()).filter(Boolean);
  if(sch.length){rule();head("Around the school and farm",14);photos(x.schoolPhotos||[]);for(const s of sch)bullet("",s)}
  {const ft=x.farms?farmNewsletterText(x.month):"";if(ft){rule();head("From our farms",14);for(const pp of ft.split(/\n\n/))para(pp)}}
  if((x.coming||[]).length){rule();head("Coming up",14);for(const c of [...x.coming].sort((a,b)=>String(a.date).localeCompare(String(b.date))))bullet(c.date?nlDay(c.date)+".":"",c.text)}
  return {doc,last:y}};
  let B=build(1);
  // a last page under a third full, or more than four pages, is worth setting a little smaller
  for(const sc of [.96,.93,.9,.87]){const n=B.doc.getNumberOfPages();if(n<2||(B.last>PH*.33&&n<=4))break;const T=build(sc);if(T.doc.getNumberOfPages()<n){B=T;break}}
  const doc=B.doc;
  const n=doc.getNumberOfPages();for(let i=1;i<=n;i++){doc.setPage(i);pfont(doc,"fr",7.6);doc.setTextColor(...C.muted);doc.text("Fulton Community School"+(n>1?`   ${i} of ${n}`:""),PW/2,PH-28,{align:"center"})}
  await saveFile(doc.output("blob"),`Fulton Community School family newsletter ${nlName(x.month)}.pdf`);
}


